tasks.register("conventionalCommits") {
    val pattern = Pattern.compile("^(feat|fix|docs|style|refactor|test|chore|build|ci)(\\(.*\\))?: .{1,50}")
    val message = File(".git/COMMIT_EDITMSG").readText().trim()
    if (!pattern.matcher(message).find()) {
        throw GradleException("Commit message does not follow Conventional Commits format.")
    }
}

tasks.register("checkBranchFiles") {
    doLast {
        val currentBranch = ByteArrayOutputStream().use { outputStream ->
            exec {
                commandLine("git", "rev-parse", "--abbrev-ref", "HEAD")
                standardOutput = outputStream
            }
            outputStream.toString().trim()
        }

        val stagedFiles = ByteArrayOutputStream().use { outputStream ->
            exec {
                commandLine("git", "diff", "--cached", "--name-only")
                standardOutput = outputStream
            }
            outputStream.toString().trim().split("\n").filter { it.isNotEmpty() }
        }

        val nonBranchFiles = stagedFiles.filter { file -> !file.startsWith("app/src/main/$currentBranch/") }

        if (nonBranchFiles.toList().isNotEmpty()) {
            println("ATTENZIONE: I seguenti file non appartengono al branch corrente (${currentBranch}):")
            nonBranchFiles.forEach { el -> println(el) }

            println("Vuoi creare una issue per questi file? (y/n): ")
            val userInput: String = readln()
            if (userInput.lowercase() == "y") {
                createIssue(currentBranch, nonBranchFiles.toList())
            } else {
                println("Vuoi procedere comunque con il commit? (y/n): ")
                val proceed = readln()
                if (proceed.lowercase() != "y") {
                    println("Commit abortito dall'utente.")
                }
            }
        }
    }
}

fun createIssue(branch: String, files: List<String>) {
    // Nota: Questo è un esempio semplificato. Dovresti usare una libreria HTTP appropriata
    val title = "File non appartenenti al branch ${branch}"
    val body = "I seguenti file non appartengono al branch ${branch}:\n\n" + files.forEach { s -> println(s + "\n") }

    val authToken = System.getenv("GITHUB_TOKEN") // Assicurati di avere questo token impostato
    val repoOwner = "BrunoEsposito2"
    val repoName = "DCCV"

    val url = URI("https://api.github.com/repos/${repoOwner}/${repoName}/issues").toURL()
    val connection = url.openConnection()

    connection.setRequestProperty("Authorization", "token ${authToken}")
    connection.setRequestProperty("Content-Type", "application/json")
    connection.doOutput = true // Triggers POST request

    val jsonPayload = """
    {
        "title": "${title}",
        "body": "${body}"
    }
    """

    connection.outputStream.write(jsonPayload.encode(Charset.forName("UTF-8")).toByteArray())

    val response = JsonSlurper().parse(connection.inputStream)
    println("Issue creata: ${response}")
}

tasks.register("buildCMake") {
    doLast {
        exec {
            commandLine("sh", "-c", """
                mkdir -p build &&
                cd build &&
                cmake .. &&
                cmake --build . &&
                cmake --install .
            """)
        }
    }
}

